#include "bookmarks.h"
#include <QCoreApplication>
#include <cstdio>
#include <stdexcept>
#include <sys/stat.h>
int main(int argc,char**argv){QCoreApplication app(argc,argv);char name[]="/tmp/inkbound20p-bookmarks.XXXXXX";auto path=mkdtemp(name);if(!path)return 2;const auto root=std::filesystem::path(path),file=root/"ui-bookmarks.json";unsigned checks=0;auto check=[&](bool b){++checks;if(!b)throw std::runtime_error("bookmark model regression");};try{const QString book="11111111-1111-4111-8111-111111111111",source(64,'a'),view(64,'b');ux::Bookmarks m;m.load(file);check(m.toggle(book,"pdf",2,20,source,view));ux::Bookmarks reopened;reopened.load(file);auto places=reopened.places(book,"pdf",20);check(places.size()==1&&places[0].page==2&&!places[0].approximate);auto exact=reopened.mark(book,places[0].mark);check(exact&&exact->page==2&&exact->source==source&&exact->viewSet==view);check(reopened.toggle(book,"pdf",5,20,source,{}));reopened.load(file);places=reopened.places(book,"pdf",20);check(places.size()==2&&reopened.mark(book,places[1].mark)->viewSet.isEmpty());check(!reopened.toggle(book,"pdf",6,20,"bad",view)&&!reopened.toggle(book,"pdf",6,20,{},view));
 QJsonArray legacyMarks{QJsonObject{{"page",4},{"pages",10},{"layout","old-layout"}}};underlay::atomicFile(file,QJsonDocument(QJsonObject{{"version",1},{"books",QJsonObject{{book,legacyMarks}}}}).toJson(QJsonDocument::Compact));reopened.load(file);places=reopened.places(book,"new-layout",19);check(places.size()==1&&places[0].page==8&&places[0].approximate);check(reopened.mark(book,places[0].mark)->source.isEmpty());check(reopened.toggle(book,"new-layout",8,19,source,view));places=reopened.places(book,"new-layout",19);check(places.size()==1&&!places[0].approximate&&reopened.mark(book,places[0].mark)->viewSet==view);
 std::filesystem::remove(file);std::filesystem::create_directory(file);check(!reopened.toggle(book,"new-layout",8,19,source,view)&&reopened.has(book,"new-layout",8));check(!reopened.mark(book,-1)&&!reopened.mark(book,100));std::filesystem::remove_all(root);std::printf("BOOKMARKS_PASS checks=%u legacy=retained exact_view_reference=roundtrip failure=no_change\n",checks);return 0;}catch(const std::exception&e){std::filesystem::remove_all(root);std::fprintf(stderr,"BOOKMARKS_FAIL %s\n",e.what());return 1;}}
